  "implementation": "def solve(case):
    import sys
    nodes = case.get('nodes')
    core = case.get('core_distance')
    distances = case.get('distances')
    if not isinstance(nodes, list) or not isinstance(core, dict) or not isinstance(distances, list):
        raise ValueError('Invalid case structure')
    node_set = set(nodes)
    if not node_set:
        raise ValueError('Empty nodes')
    if set(core.keys()) != node_set:
        raise ValueError('core_distance keys mismatch')
    edges = []
    for item in distances:
        if len(item) != 3:
            raise ValueError('Invalid distance entry')
        u, v, d = item
        if u not in node_set or v not in node_set:
            raise ValueError('Unknown node in distance')
        if u == v:
            continue
        cu = core[u]
        cv = core[v]
        mutual = max(cu, cv, d)
        a, b = (u, v) if u <= v else (v, u)
        edges.append((mutual, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        elif rank[rx] == rank[ry]:
            if rx > ry:
                rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True
    selected = []
    total = 0.0
    n = len(nodes)
    for mutual, a, b in edges:
        if union(a, b):
            selected.append([a, b, mutual])
            total += mutual
            if len(selected) == n - 1:
                break
    if len(selected) != n - 1:
        raise ValueError('Graph is disconnected or insufficient edges for MST')
    return {'edges': selected, 'total_weight': total}"
